CREATE TABLE IF NOT EXISTS "availability" ("id" serial PRIMARY KEY NOT NULL,"starts_at" timestamp with time zone NOT NULL,"ends_at" timestamp with time zone NOT NULL,"status" text DEFAULT 'open' NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "appointments" ("id" serial PRIMARY KEY NOT NULL,"name" text NOT NULL,"email" text NOT NULL,"phone" text DEFAULT '' NOT NULL,"company" text DEFAULT '' NOT NULL,"project_type" text DEFAULT 'Website' NOT NULL,"starts_at" timestamp with time zone NOT NULL,"duration_minutes" integer DEFAULT 45 NOT NULL,"status" text DEFAULT 'booked' NOT NULL,"notes" text DEFAULT '' NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "appointments_starts_at_unique" ON "appointments" ("starts_at") WHERE "status" = 'booked';
